const rows = orders.map(o => `${o.id},"${o.items}",$${o.total}`);
const csv = [header, ...rows].join('\n') + '\n';

fs.writeFileSync('/workspace/data/confirmed_orders.csv', csv);
console.log(`Saved ${orders.length} confirmed orders to /workspace/data/confirmed_orders.csv`);
console.log(csv);
```

